<template><section class="link-parameters"><header><strong>{{ title }}</strong><button type="button" :disabled="modelValue.length >= 20" :title="`添加${title}`" @click="update([...modelValue, { key: '', value: '' }])"><Plus :size="16" /></button></header><div v-for="(row,index) in modelValue" :key="index" class="parameter-row"><label><FormFieldLabel :required="secret || Boolean(row.key || row.value)" help="1 至 80 位字母、数字、下划线、点或连字符">参数名</FormFieldLabel><el-input :model-value="row.key" placeholder="参数名" maxlength="80" @update:model-value="value => change(index,'key',value)" /></label><label><FormFieldLabel :required="false" :help="secret ? '最多 4000 字节，不能包含换行或空字符' : '最多 1000 个字符；名称和值均为空时，此行不保存'">参数值</FormFieldLabel><el-input :model-value="row.value" :type="secret ? 'password' : 'text'" :show-password="secret" placeholder="参数值" :maxlength="secret ? 4000 : 1000" @update:model-value="value => change(index,'value',value)" /></label><button type="button" title="移除参数" @click="update(modelValue.filter((_,i) => i !== index))"><X :size="16" /></button></div></section></template>
<script setup>
import FormFieldLabel from '../../../shared/components/FormFieldLabel.vue';
import { Plus, X } from '@lucide/vue';
const props = defineProps({ modelValue: { type: Array, default: () => [] }, title: String, secret: Boolean });
const emit = defineEmits(['update:modelValue']);
function update(value) { emit('update:modelValue', value); }
function change(index, key, value) { update(props.modelValue.map((row,i) => i === index ? { ...row, [key]:value } : row)); }
</script>
<style scoped>.parameter-row label{display:grid;gap:6px;min-width:0}.link-parameters{display:flex;flex-direction:column;gap:10px;min-width:0}.link-parameters header{display:flex;align-items:center;justify-content:space-between;font-size:13px;padding:0;border:0;background:transparent;min-height:30px}.link-parameters button{display:grid;place-items:center;border:0;background:transparent;color:var(--muted);min-width:30px;height:30px;cursor:pointer}.parameter-row{display:grid;grid-template-columns:minmax(90px,1fr) minmax(130px,2fr) 30px;gap:8px;align-items:center}</style>
